1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = { itemType: string; amount: number };
9	
10	export type Step =
11	  | { op: "quote"; items: Item[] }
12	  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
13	
14	export type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };
15	
16	export type QuoteResult = { premium: number };
17	export type ClaimResult = { payout: number; remainingCap: number };
18	export type Result = QuoteResult | ClaimResult;
19	
20	const PROCESSING_FEE = 5;
21	// Every damage event carries a deductible, borne by the customer.
22	const DEDUCTIBLE_PER_DAMAGE_EVENT = 100;
23	const BASE_PREMIUMS: Record<string, number> = {
24	  sword: 100,
25	  amulet: 60,
26	  staff: 80,
27	  potion: 40,
28	  rune: 25,
29	  moonstone: 25,
30	};
31	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
32	const LOYALTY_YEARS_THRESHOLD = 2;
33	const LOYALTY_DISCOUNT_RATE = 0.2;
34	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
35	const CURSE_SURCHARGE_RATE = 0.5;
36	const HIGH_ENCHANTMENT_THRESHOLD = 5;
37	const ENCHANTMENT_SURCHARGE_RATE = 0.3;
38	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
39	// A building block of alike components is priced as a unit, not per piece.
40	const COMPONENT_BLOCK_SIZE = 3;
41	const COMPONENT_BLOCK_PREMIUM = 60;
42	// Unmodified insurance value per item; the sum over a policy bounds what can be paid out.
43	const INSURANCE_VALUES: Record<string, number> = {
44	  sword: 1000,
45	  amulet: 600,
46	  rune: 250,
47	};
48	// A policy pays out at most twice its insurance sum.
49	const PAYOUT_CAP_MULTIPLIER = 2;
50	// Damage to strongly enchanted items is only partially reimbursed (a stricter bar than the premium surcharge).
51	const PARTIAL_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
52	const PARTIAL_REIMBURSEMENT_RATE = 0.5;
53	
54	const isComponent = (type: string): boolean => COMPONENT_TYPES.has(type);
55	
56	const formsBlock = (type: string, count: number): boolean =>
57	  isComponent(type) && count === COMPONENT_BLOCK_SIZE;
58	
59	const premiumForTypeGroup = (type: string, count: number): number =>
60	  formsBlock(type, count) ? COMPONENT_BLOCK_PREMIUM : count * BASE_PREMIUMS[type];
61	
62	const countWhere = <T>(elements: T[], matches: (element: T) => boolean): number =>
63	  elements.filter(matches).length;
64	
65	const countOfType = (items: Item[], type: string): number =>
66	  countWhere(items, (item) => item.type === type);
67	
68	const calculateBasePremium = (items: Item[]): number => {
69	  const types = [...new Set(items.map((item) => item.type))];
70	  return types.reduce(
71	    (total, type) => total + premiumForTypeGroup(type, countOfType(items, type)),
72	    0,
73	  );
74	};
75	
76	// Item-specific modifiers: each applies a rate to the base premium of every affected item.
77	const itemSurcharge = (items: Item[], applies: (item: Item) => boolean, rate: number): number =>
78	  items
79	    .filter(applies)
80	    .reduce((sum, item) => sum + BASE_PREMIUMS[item.type] * rate, 0);
81	
82	const isCursed = (item: Item): boolean => item.cursed === true;
83	
84	// An item without an enchantment counts as enchantment level 0.
85	const enchantmentLevel = (item: Item): number => item.enchantment ?? 0;
86	
87	const isHighlyEnchanted = (item: Item): boolean =>
88	  enchantmentLevel(item) >= HIGH_ENCHANTMENT_THRESHOLD;
89	
90	const curseSurcharge = (items: Item[]): number =>
91	  itemSurcharge(items, isCursed, CURSE_SURCHARGE_RATE);
92	
93	const enchantmentSurcharge = (items: Item[]): number =>
94	  itemSurcharge(items, isHighlyEnchanted, ENCHANTMENT_SURCHARGE_RATE);
95	
96	// Policy-wide modifiers: each applies to the policy base premium (sum of item base premiums).
97	const firstInsuranceSurcharge = (basePremium: number): number =>
98	  basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
99	
100	const isLoyalCustomer = (yearsWithMHPCO: number): boolean =>
101	  yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
102	
103	const loyaltyDiscount = (basePremium: number, yearsWithMHPCO: number): number =>
104	  isLoyalCustomer(yearsWithMHPCO) ? basePremium * LOYALTY_DISCOUNT_RATE : 0;
105	
106	const followUpDiscount = (basePremium: number, isFollowUpContract: boolean): number =>
107	  isFollowUpContract ? basePremium * FOLLOW_UP_DISCOUNT_RATE : 0;
108	
109	// Premiums are rounded up to whole G, in the MHPCO's favour.
110	const roundUpToWholeGold = (amount: number): number => Math.ceil(amount);
111	
112	// Payouts are rounded down to whole G, in the MHPCO's favour.
113	const roundDownToWholeGold = (amount: number): number => Math.floor(amount);
114	
115	// What the MHPCO knows about the customer at the moment a quote is issued.
116	type CustomerContext = { yearsWithMHPCO: number; isFollowUpContract: boolean };
117	
118	// The MHPCO only insures item types it has a base premium for.
119	const isKnownItemType = (type: string): boolean => type in BASE_PREMIUMS;
120	
121	const assertKnownItemType = (type: string): void => {
122	  if (!isKnownItemType(type)) throw new Error(`Unknown item type: ${type}`);
123	};
124	
125	const assertKnownItemTypes = (items: Item[]): void =>
126	  items.forEach((item) => assertKnownItemType(item.type));
127	
128	const quotePremium = (items: Item[], customer: CustomerContext): number => {
129	  assertKnownItemTypes(items);
130	  const basePremium = calculateBasePremium(items);
131	  const premiumBeforeFee =
132	    basePremium +
133	    curseSurcharge(items) +
134	    enchantmentSurcharge(items) +
135	    firstInsuranceSurcharge(basePremium) -
136	    loyaltyDiscount(basePremium, customer.yearsWithMHPCO) -
137	    followUpDiscount(basePremium, customer.isFollowUpContract);
138	  return roundUpToWholeGold(premiumBeforeFee + PROCESSING_FEE);
139	};
140	
141	const isPartiallyReimbursed = (item: Item): boolean =>
142	  enchantmentLevel(item) >= PARTIAL_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
143	
144	const reimbursedAmount = (item: Item, damage: Damage): number =>
145	  isPartiallyReimbursed(item) ? damage.amount * PARTIAL_REIMBURSEMENT_RATE : damage.amount;
146	
147	const findDamagedItem = (insuredItems: Item[], damage: Damage): Item | undefined =>
148	  insuredItems.find((candidate) => candidate.type === damage.itemType);
149	
150	const payoutForDamage = (insuredItems: Item[], damage: Damage): number => {
151	  const item = findDamagedItem(insuredItems, damage);
152	  if (item === undefined) throw new Error(`Damaged item not covered by policy: ${damage.itemType}`);
153	  return reimbursedAmount(item, damage) - DEDUCTIBLE_PER_DAMAGE_EVENT;
154	};
155	
156	const claimPayout = (insuredItems: Item[], damages: Damage[]): number =>
157	  damages.reduce((total, damage) => total + payoutForDamage(insuredItems, damage), 0);
158	
159	const countDamagesOfType = (damages: Damage[], type: string): number =>
160	  countWhere(damages, (damage) => damage.itemType === type);
161	
162	// Each damaged item must be covered by a distinct insured item of the same type.
163	const assertDamageCovered = (insuredItems: Item[], damages: Damage[], damage: Damage): void => {
164	  const { itemType } = damage;
165	  if (damage.amount < 0) {
166	    throw new Error(`Negative damage amount for ${itemType}: ${damage.amount}`);
167	  }
168	  if (countDamagesOfType(damages, itemType) > countOfType(insuredItems, itemType)) {
169	    throw new Error(`More damages than insured items of type: ${itemType}`);
170	  }
171	};
172	
173	const assertDamagesCovered = (insuredItems: Item[], damages: Damage[]): void =>
174	  damages.forEach((damage) => assertDamageCovered(insuredItems, damages, damage));
175	
176	const insuranceSum = (items: Item[]): number =>
177	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
178	
179	const payoutCap = (items: Item[]): number => insuranceSum(items) * PAYOUT_CAP_MULTIPLIER;
180	
181	// A policy: the items it covers and how much it may still pay out.
182	type Policy = { items: Item[]; remainingCap: number };
183	
184	const openPolicy = (items: Item[]): Policy => ({ items, remainingCap: payoutCap(items) });
185	
186	const settleClaim = (policy: Policy, damages: Damage[]): ClaimResult => {
187	  assertDamagesCovered(policy.items, damages);
188	  const payout = roundDownToWholeGold(
189	    Math.min(claimPayout(policy.items, damages), policy.remainingCap),
190	  );
191	  return { payout, remainingCap: policy.remainingCap - payout };
192	};
193	
194	// Every contract after the customer's first in a scenario is a follow-up contract.
195	const isFollowUpContract = (stepIndex: number): boolean => stepIndex > 0;
196	
197	const customerContextAt = (scenario: Scenario, stepIndex: number): CustomerContext => ({
198	  yearsWithMHPCO: scenario.customer.yearsWithMHPCO,
199	  isFollowUpContract: isFollowUpContract(stepIndex),
200	});
201	
202	export const runScenario = (scenario: Scenario): { results: Result[] } => {
203	  // Policies are referenced by the index of the quote step that created them.
204	  const policies = new Map<number, Policy>();
205	  const results = scenario.steps.map((step, index): Result => {
206	    if (step.op === "claim") {
207	      const policy = policies.get(step.policy) ?? openPolicy([]);
208	      const result = settleClaim(policy, step.incident.damages);
209	      policies.set(step.policy, { ...policy, remainingCap: result.remainingCap });
210	      return result;
211	    }
212	    policies.set(index, openPolicy(step.items));
213	    return { premium: quotePremium(step.items, customerContextAt(scenario, index)) };
214	  });
215	  return { results };
216	};
